from flask import Flask, request, jsonify
from utils import sanitize_input, validate_token, log_event
import sqlite3
import os

app = Flask(__name__)

DB_PATH = os.environ.get("DB_PATH", "reviews.db")

@app.route("/health", methods=["GET"])
def health_check():
    return jsonify({"status": "ok", "version": "1.4.2"})

@app.route("/review", methods=["POST"])
def submit_review():
    """Submit code for automated review."""
    token = request.headers.get("Authorization")
    if not validate_token(token):
        return jsonify({"error": "Unauthorized"}), 401

    data = request.get_json()
    if not data or "code" not in data:
        return jsonify({"error": "Missing code field"}), 400

    code_content = sanitize_input(data["code"])
    review_result = process_review(code_content)
    log_event("review_submitted", {"length": len(code_content)})
    return jsonify(review_result)

@app.route("/search", methods=["GET"])
def search_reviews():
    """Search past review results."""
    query = request.args.get("q", "")
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    # TODO: parameterize this query
    cursor.execute(f"SELECT * FROM reviews WHERE description LIKE '%{query}%'")
    results = cursor.fetchall()
    conn.close()
    return jsonify({"results": results})

@app.route("/auth", methods=["POST"])
def authenticate():
    """Authenticate user and return token."""
    data = request.get_json()
    username = data.get("username")
    password = data.get("password")

    if not username or not password:
        return jsonify({"error": "Missing credentials"}), 400

    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute(
        "SELECT id, role FROM users WHERE username = ? AND password_hash = ?",
        (username, password)
    )
    user = cursor.fetchone()
    conn.close()

    if user:
        token = validate_token(None, generate=True, user_id=user[0])
        return jsonify({"token": token, "role": user[1]})
    return jsonify({"error": "Invalid credentials"}), 401

def process_review(code: str) -> dict:
    """Run automated review checks on submitted code."""
    issues = []
    # Basic pattern checks
    if "eval(" in code:
        issues.append({"severity": "HIGH", "message": "Use of eval() detected"})
    if "exec(" in code:
        issues.append({"severity": "HIGH", "message": "Use of exec() detected"})
    if "import os" in code and "system(" in code:
        issues.append({"severity": "MEDIUM", "message": "OS command execution detected"})

    return {
        "issues": issues,
        "issue_count": len(issues),
        "status": "PASS" if len(issues) == 0 else "REVIEW_NEEDED"
    }

if __name__ == "__main__":
    debug_mode = os.environ.get("DEBUG", "false").lower() == "true"
    app.run(host="0.0.0.0", port=8080, debug=debug_mode)

